'use strict';

/**
 * #876 — a declared `bin` / `main` that is generated is not source.
 *
 * A project that ships a bundle as its `bin` (SigMap's own `gen-context.js`, a
 * `dist/cli.js`) has that file pulled into the index as a declared entrypoint, even
 * though srcDirs never reached it. Every function in `src/` then appeared twice, once
 * at its real path and once inside the bundle, the budget paid for both, and the
 * `changes` and `todos` sections reported the bundle's copies.
 *
 *   1. `generatedReason` recognises a generated file from its path and its first and
 *      last bytes, and does not take prose that mentions generated code for a header
 *   2. a generated declared entrypoint is left out of the index, with srcDirs narrow
 *      and with srcDirs ['.'] (where a plain walk reaches it)
 *   3. a hand-written declared entrypoint is still indexed
 *   4. a symbol that exists in `src/` and again in the bundle is listed once
 *   5. `.contextignore` is honoured for a declared entrypoint
 *   6. `explain` says why a generated entrypoint is excluded, and no longer calls an
 *      indexed hand-written entrypoint outside srcDirs "not under any srcDir"
 *   7. SigMap's own bundle is recognised
 *
 * Each of 2-6 fails on the code before this change.
 */

const assert = require('assert');
const path = require('path');
const fs = require('fs');
const os = require('os');
const { spawnSync } = require('child_process');

const ROOT = path.resolve(__dirname, '../..');
const SCRIPT = path.join(ROOT, 'gen-context.js');
const { generatedReason } = require(path.join(ROOT, 'src', 'util', 'file-class'));

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`  PASS  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  FAIL  ${name}`);
    console.error(`        ${err.message}`);
    failed++;
  }
}

const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'sigmap-genentry-'));
let counter = 0;

/** A repo with `files` (path → text), a package.json and an optional config. */
function repo(files, pkg, config) {
  const dir = path.join(tmpRoot, `r${counter++}`);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, 'package.json'), JSON.stringify({ name: 'fx', version: '1.0.0', ...pkg }));
  if (config) fs.writeFileSync(path.join(dir, 'gen-context.config.json'), JSON.stringify(config));
  for (const [rel, text] of Object.entries(files)) {
    const abs = path.join(dir, rel);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, text);
  }
  return dir;
}

function sigmap(dir, args = []) {
  return spawnSync('node', [SCRIPT, ...args], { cwd: dir, encoding: 'utf8' });
}

/** Paths in the retrieval index after a run. */
function indexed(dir) {
  const res = sigmap(dir);
  assert.strictEqual(res.status, 0, `generation failed:\n${res.stdout}${res.stderr}`);
  return Object.keys(JSON.parse(fs.readFileSync(path.join(dir, '.context', 'sig-index.json'), 'utf8')).files);
}

const APP = 'function parseConfig(text) { return JSON.parse(text); }\nfunction renderPage(model) { return String(model); }\nmodule.exports = { parseConfig, renderPage };\n';
const BUNDLE = [
  '#!/usr/bin/env node',
  "'use strict';",
  '// standalone bundle (modules generated by build.js)',
  APP.trim(),
  'function main() { return 0; }',
  '',
].join('\n');
const HAND = '#!/usr/bin/env node\n\'use strict\';\n// Command line entry: reads a file and prints it.\nfunction runCli(argv) { return argv.length; }\nrunCli(process.argv);\n';

// ---------------------------------------------------------------------------
// 1. The detector
// ---------------------------------------------------------------------------
test('generatedReason reads each signal: path, header, runtime helpers, source map', () => {
  assert.ok(generatedReason('dist/cli.js', '', ''), 'a build-output directory');
  assert.ok(generatedReason('api/user.pb.js', '', ''), 'a machine-emitted file name');
  assert.ok(generatedReason('a.js', '// @generated by tool\nconst x = 1;\n', ''), '@generated');
  assert.ok(generatedReason('a.js', '/* This file is autogenerated by build.js, do not edit */\n', ''), 'autogenerated');
  assert.ok(generatedReason('a.js', '// Generated By cn-font-split@5\n', ''), 'a capitalised Generated opener');
  assert.ok(generatedReason('a.js', '// GENERATED CODE -- DO NOT EDIT!\n', ''), 'do not edit');
  assert.ok(generatedReason('a.js', '/* generated during release, do not modify */\n', ''), 'do not modify');
  assert.ok(generatedReason('a.js', '// standalone bundle (modules generated by build.js)\n', ''), 'a generated bundle');
  assert.ok(generatedReason('a.js', '/******/ (() => { // webpackBootstrap\n', ''), 'webpack runtime');
  assert.ok(generatedReason('a.js', 'var __defProp = Object.defineProperty;\nvar __commonJS = (cb) => cb;\n', ''), 'esbuild helpers');
  assert.ok(generatedReason('a.js', '"use strict";\nObject.defineProperty(exports, "__esModule", { value: true });\n', ''), 'compiled TypeScript');
  assert.ok(generatedReason('a.js', 'const a = 1;\n', 'x\n//# sourceMappingURL=a.js.map\n'), 'a source map reference');
});

test('generatedReason does not take prose about generated code for a header', () => {
  // The wrapped JSDoc line that began with a lowercase "generated" (astro's actions/handler.ts)
  assert.strictEqual(generatedReason('src/handler.ts', '/**\n * Handles the request from the browser\n *   generated JS client). Runs the action.\n */\nexport function handle() {}\n', ''), null);
  assert.strictEqual(generatedReason('bin/cli.js', '#!/usr/bin/env node\n// Reads the files webpack generated and prints them.\nrun();\n', ''), null);
  assert.strictEqual(generatedReason('bin/cli.js', HAND, ''), null);
  assert.strictEqual(generatedReason('lib/index.js', "const regenerated = 1; // not a header\n", ''), null);
  assert.strictEqual(generatedReason('src/a.ts', 'export const x = 1;\n', 'export const y = 2;\n'), null);
});

test("SigMap's own bundle is recognised, and its hand-written siblings are not", () => {
  const read = (f) => fs.readFileSync(path.join(ROOT, f), 'utf8');
  const g = read('gen-context.js');
  assert.ok(generatedReason('gen-context.js', g.slice(0, 4096), g.slice(-512)), 'gen-context.js');
  const m = read('gen-project-map.js');
  assert.strictEqual(generatedReason('gen-project-map.js', m.slice(0, 4096), m.slice(-512)), null);
  const c = read('packages/core/index.js');
  assert.strictEqual(generatedReason('packages/core/index.js', c.slice(0, 4096), c.slice(-512)), null);
});

// ---------------------------------------------------------------------------
// 2-4. What the index holds
// ---------------------------------------------------------------------------
test('a generated bin outside srcDirs is not indexed, and the source it repeats is listed once', () => {
  const dir = repo({ 'src/app.js': APP, 'cli.js': BUNDLE }, { bin: { fx: 'cli.js' } }, { srcDirs: ['src'] });
  const files = indexed(dir);
  assert.ok(files.includes('src/app.js'), files.join('\n'));
  assert.ok(!files.includes('cli.js'), `the bundle is indexed:\n${files.join('\n')}`);
  const idx = JSON.parse(fs.readFileSync(path.join(dir, '.context', 'sig-index.json'), 'utf8')).files;
  const carriers = Object.keys(idx).filter((f) => idx[f].some((s) => /parseConfig/.test(s)));
  assert.deepStrictEqual(carriers, ['src/app.js'], 'parseConfig is listed once');
});

test('a generated main is not indexed when srcDirs is the whole repository either', () => {
  const dir = repo({ 'src/app.js': APP, 'index.js': BUNDLE }, { main: 'index.js' }, { srcDirs: ['.'] });
  const files = indexed(dir);
  assert.ok(files.includes('src/app.js'), files.join('\n'));
  assert.ok(!files.includes('index.js'), `the bundle is indexed:\n${files.join('\n')}`);
});

test('a hand-written bin outside srcDirs is still indexed', () => {
  const dir = repo({ 'src/app.js': APP, 'cli.js': HAND }, { bin: { fx: 'cli.js' } }, { srcDirs: ['src'] });
  const files = indexed(dir);
  assert.ok(files.includes('cli.js'), `the hand-written entrypoint is missing:\n${files.join('\n')}`);
  assert.ok(files.includes('src/app.js'), files.join('\n'));
});

test('a bin under a build-output directory is not indexed; a hand-written one beside it is', () => {
  const dir = repo({ 'src/app.js': APP, 'dist/cli.js': HAND, 'tools/run.js': HAND }, { bin: { a: 'dist/cli.js', b: 'tools/run.js' } }, { srcDirs: ['src'] });
  const files = indexed(dir);
  assert.ok(!files.includes('dist/cli.js'), files.join('\n'));
  assert.ok(files.includes('tools/run.js'), files.join('\n'));
});

// ---------------------------------------------------------------------------
// 5. Ignore patterns
// ---------------------------------------------------------------------------
test('.contextignore keeps a declared entrypoint out of the index', () => {
  const dir = repo({ 'src/app.js': APP, 'cli.js': HAND, '.contextignore': 'cli.js\n' }, { bin: { fx: 'cli.js' } }, { srcDirs: ['src'] });
  const files = indexed(dir);
  assert.ok(!files.includes('cli.js'), files.join('\n'));
  assert.ok(files.includes('src/app.js'), files.join('\n'));
});

// ---------------------------------------------------------------------------
// 6. explain
// ---------------------------------------------------------------------------
test('explain names a generated entrypoint as excluded and says why', () => {
  const dir = repo({ 'src/app.js': APP, 'cli.js': BUNDLE }, { bin: { fx: 'cli.js' } }, { srcDirs: ['src'] });
  const res = sigmap(dir, ['explain', 'cli.js']);
  assert.strictEqual(res.status, 0, res.stderr);
  assert.ok(/EXCLUDED/.test(res.stdout), res.stdout);
  assert.ok(/generated entrypoint/.test(res.stdout), res.stdout);
  assert.ok(/generated bundle/.test(res.stdout), 'the reason names the signal: ' + res.stdout);
  const json = JSON.parse(sigmap(dir, ['explain', 'cli.js', '--json']).stdout);
  assert.strictEqual(json.status, 'excluded');
  assert.strictEqual(json.reason, 'generated entrypoint');
});

test('explain calls a hand-written declared entrypoint outside srcDirs included', () => {
  const dir = repo({ 'src/app.js': APP, 'cli.js': HAND }, { bin: { fx: 'cli.js' } }, { srcDirs: ['src'] });
  const res = sigmap(dir, ['explain', 'cli.js']);
  assert.ok(/INCLUDED/.test(res.stdout), res.stdout);
  assert.ok(!/not under any srcDir/.test(res.stdout), res.stdout);
});

test('the MCP explain_file tool says a generated file is generated, not "run gen-context.js"', () => {
  const { explainFile } = require(path.join(ROOT, 'src', 'mcp', 'handlers'));
  const dir = repo({ 'src/app.js': APP, 'cli.js': BUNDLE }, { bin: { fx: 'cli.js' } }, { srcDirs: ['src'] });
  indexed(dir);
  const out = explainFile({ path: 'cli.js' }, dir);
  assert.ok(/looks generated/.test(out), out);
  assert.ok(!/Run: node gen-context\.js/.test(out), 'advice that cannot help: ' + out);
  // an ordinary unindexed file keeps the old remedy
  fs.writeFileSync(path.join(dir, 'notes.txt'), 'plain text\n');
  assert.ok(/Run: node gen-context\.js/.test(explainFile({ path: 'notes.txt' }, dir)));
});

try { fs.rmSync(tmpRoot, { recursive: true, force: true }); } catch (_) {}

console.log(`\ngenerated-entrypoint: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
